<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Balloon Pop Archery</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Press+Start+2P&family=VT323&display=swap" rel="stylesheet">
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #1a1a2e; }
  body { display: flex; align-items: center; justify-content: center; }
  #wrap { position: relative; }
  canvas { display: block; image-rendering: pixelated; cursor: crosshair; }
  .overlay {
    position: absolute; inset: 0; display: flex; flex-direction: column;
    align-items: center; justify-content: center; z-index: 10;
    background: rgba(10,10,30,0.82); color: #fff; text-align: center;
    font-family: 'VT323', monospace;
  }
  .overlay.hidden { display: none; }
  .title {
    font-family: 'Press Start 2P', monospace; font-size: 28px;
    color: #ffd23f; text-shadow: 3px 3px 0 #b03030, 6px 6px 0 rgba(0,0,0,.4);
    margin-bottom: 24px; line-height: 1.5;
  }
  .subtitle { font-size: 26px; color: #a8d8ff; margin-bottom: 8px; }
  .hint { font-size: 20px; color: #888; margin-top: 18px; line-height: 1.6; }
  .score-big { font-family: 'Press Start 2P', monospace; font-size: 40px; color: #7CFC00; margin: 16px 0; text-shadow: 2px 2px 0 #000; }
  .btn {
    font-family: 'Press Start 2P', monospace; font-size: 16px;
    color: #1a1a2e; background: #ffd23f; border: none; padding: 16px 32px;
    cursor: pointer; margin-top: 24px; box-shadow: 0 6px 0 #b8860b;
    transition: transform .05s;
  }
  .btn:active { transform: translateY(4px); box-shadow: 0 2px 0 #b8860b; }
</style>
</head>
<body>
<div id="wrap">
  <canvas id="c"></canvas>
  <div id="startScreen" class="overlay">
    <div class="title">BALLOON<br>ARCHERY</div>
    <div class="subtitle">Level 1 &mdash; Pop them all!</div>
    <div class="hint">
      Aim with the mouse &middot; Hold left button to draw the bow<br>
      Release to fire &middot; Pop all 10 balloons before you run out of arrows
    </div>
    <button class="btn" id="startBtn">START</button>
  </div>
  <div id="endScreen" class="overlay hidden">
    <div class="title" id="endTitle">GAME OVER</div>
    <div class="score-big" id="finalScore">0</div>
    <div class="subtitle" id="endMsg"></div>
    <button class="btn" id="retryBtn">PLAY AGAIN</button>
  </div>
</div>
<script>
(() => {
"use strict";
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
let W = 960, H = 600;
canvas.width = W; canvas.height = H;

// ---------- Audio ----------
let AC = null;
function audio() {
  if (!AC) AC = new (window.AudioContext || window.webkitAudioContext)();
  if (AC.state === 'suspended') AC.resume();
  return AC;
}
function blip(freq, dur, type='square', vol=0.15, slide=0) {
  const ac = audio();
  const o = ac.createOscillator(), g = ac.createGain();
  o.type = type; o.frequency.value = freq;
  if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), ac.currentTime + dur);
  g.gain.setValueAtTime(vol, ac.currentTime);
  g.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + dur);
  o.connect(g).connect(ac.destination);
  o.start(); o.stop(ac.currentTime + dur);
}
const sfx = {
  draw: () => blip(120, 0.1, 'sawtooth', 0.05, 80),
  shoot: () => { blip(300, 0.12, 'square', 0.12, -200); blip(150, 0.15, 'triangle', 0.1, -100); },
  pop: () => { blip(600, 0.08, 'square', 0.2, 300); blip(900, 0.06, 'sine', 0.15, 200); },
  miss: () => blip(100, 0.2, 'sawtooth', 0.08, -50),
  win: () => { [523,659,784,1047].forEach((f,i)=>setTimeout(()=>blip(f,0.25,'square',0.15),i*120)); },
  lose: () => { [400,350,300,200].forEach((f,i)=>setTimeout(()=>blip(f,0.3,'sawtooth',0.12),i*150)); },
};

